// EncodeOut lays one Out payload out as an inline list element:
// the fixed section alone, unaligned, exactly as wide as the stride.
inline std::array<std::uint8_t, static_cast<std::size_t>(kOutSize)> EncodeOut(const OutInput& in) {
    std::array<std::uint8_t, static_cast<std::size_t>(kOutSize)> e{};
    std::memcpy(e.data() + kOutAssetOff, in.Asset.data(), 32);
    zap::store_u64(e.data() + kOutStakeLockOff, in.StakeLock);
    zap::store_u64(e.data() + kOutAmountOff, in.Amount);
    zap::store_u32(e.data() + kOutThresholdOff, in.Threshold);
    zap::store_u64(e.data() + kOutOwnerLockOff, in.OwnerLock);
    zap::store_u32(e.data() + kOutAddrStartOff, in.AddrStart);
    zap::store_u32(e.data() + kOutAddrCountOff, in.AddrCount);
    return e;
}

// AppendOut writes one Out object into b — every payload it points at first,
// then the object itself — and returns the object's offset.
inline std::int64_t AppendOut(zap::Builder& b, const OutInput& in) {
    auto ob = b.start_object(kOutSize);
    ob.set_bytes_fixed(kOutAssetOff, std::span<const std::uint8_t>(in.Asset));
    ob.set_u64(kOutStakeLockOff, in.StakeLock);
    ob.set_u64(kOutAmountOff, in.Amount);
    ob.set_u32(kOutThresholdOff, in.Threshold);
    ob.set_u64(kOutOwnerLockOff, in.OwnerLock);
    ob.set_u32(kOutAddrStartOff, in.AddrStart);
    ob.set_u32(kOutAddrCountOff, in.AddrCount);
    return ob.finish();
}

// NewOut writes a ZAP-encoded Out message into a fresh buffer and returns it.
inline std::vector<std::uint8_t> NewOut(const OutInput& in) {
    zap::Builder b(256, zap::kVersion2);
    auto ob = b.start_object(kOutSize);
    ob.set_bytes_fixed(kOutAssetOff, std::span<const std::uint8_t>(in.Asset));
    ob.set_u64(kOutStakeLockOff, in.StakeLock);
    ob.set_u64(kOutAmountOff, in.Amount);
    ob.set_u32(kOutThresholdOff, in.Threshold);
    ob.set_u64(kOutOwnerLockOff, in.OwnerLock);
    ob.set_u32(kOutAddrStartOff, in.AddrStart);
    ob.set_u32(kOutAddrCountOff, in.AddrCount);
    ob.finish_as_root();
    return b.finish();
}

