// AppendBase writes one Base object into b — every payload it points at first,
// then the object itself — and returns the object's offset.
inline std::int64_t AppendBase(zap::Builder& b, const BaseInput& in) {
    std::int64_t outs_off = 0;
    if (!in.Outs.empty()) {
        auto lb = b.start_list(72);
        for (const auto& elem : in.Outs) {
            const auto payload = EncodeOut(elem);
            lb.add_bytes(payload);
        }
        outs_off = lb.finish().first;
    }
    std::int64_t ownerAddrs_off = 0;
    if (!in.OwnerAddrs.empty()) {
        auto lb = b.start_list(20);
        for (const auto& elem : in.OwnerAddrs) lb.add_bytes(elem);
        ownerAddrs_off = lb.finish().first;
    }
    std::int64_t ins_off = 0;
    if (!in.Ins.empty()) {
        auto lb = b.start_list(96);
        for (const auto& elem : in.Ins) {
            const auto payload = EncodeIn(elem);
            lb.add_bytes(payload);
        }
        ins_off = lb.finish().first;
    }
    std::int64_t sigIndices_off = 0;
    if (!in.SigIndices.empty()) {
        auto lb = b.start_list(4);
        for (const auto& elem : in.SigIndices) lb.add_u32(elem);
        sigIndices_off = lb.finish().first;
    }
    auto ob = b.start_object(kBaseSize);
    ob.set_u8(kBaseKindOff, in.Kind);
    ob.set_u32(kBaseNetworkIDOff, in.NetworkID);
    ob.set_bytes_fixed(kBaseBlockchainIDOff, std::span<const std::uint8_t>(in.BlockchainID));
    ob.set_list(kBaseOutsOff, outs_off, static_cast<std::int64_t>(in.Outs.size()));
    ob.set_list(kBaseOwnerAddrsOff, ownerAddrs_off, static_cast<std::int64_t>(in.OwnerAddrs.size()));
    ob.set_list(kBaseInsOff, ins_off, static_cast<std::int64_t>(in.Ins.size()));
    ob.set_list(kBaseSigIndicesOff, sigIndices_off, static_cast<std::int64_t>(in.SigIndices.size()));
    ob.set_bytes(kBaseMemoOff, in.Memo);
    return ob.finish();
}

