// EncodeNetworkValidator lays one NetworkValidator payload out as an inline list element:
// the fixed section alone, unaligned, exactly as wide as the stride.
inline std::array<std::uint8_t, static_cast<std::size_t>(kNetworkValidatorSize)> EncodeNetworkValidator(const NetworkValidatorInput& in) {
    std::array<std::uint8_t, static_cast<std::size_t>(kNetworkValidatorSize)> e{};
    zap::store_u64(e.data() + kNetworkValidatorWeightOff, in.Weight);
    zap::store_u64(e.data() + kNetworkValidatorBalanceOff, in.Balance);
    std::memcpy(e.data() + kNetworkValidatorSignerKeyOff, in.SignerKey.data(), 48);
    std::memcpy(e.data() + kNetworkValidatorSignerProofOff, in.SignerProof.data(), 96);
    zap::store_u32(e.data() + kNetworkValidatorNodeIDStartOff, in.NodeIDStart);
    zap::store_u32(e.data() + kNetworkValidatorNodeIDLenOff, in.NodeIDLen);
    zap::store_u32(e.data() + kNetworkValidatorRemoveThresholdOff, in.RemoveThreshold);
    zap::store_u32(e.data() + kNetworkValidatorRemoveAddrStartOff, in.RemoveAddrStart);
    zap::store_u32(e.data() + kNetworkValidatorRemoveAddrCountOff, in.RemoveAddrCount);
    zap::store_u32(e.data() + kNetworkValidatorDisableThresholdOff, in.DisableThreshold);
    zap::store_u32(e.data() + kNetworkValidatorDisableAddrStartOff, in.DisableAddrStart);
    zap::store_u32(e.data() + kNetworkValidatorDisableAddrCountOff, in.DisableAddrCount);
    return e;
}

