// EncodeDecided lays one Decided payload out as an inline list element:
// the fixed section alone, unaligned, exactly as wide as the stride.
inline std::array<std::uint8_t, static_cast<std::size_t>(kDecidedSize)> EncodeDecided(const DecidedInput& in) {
    std::array<std::uint8_t, static_cast<std::size_t>(kDecidedSize)> e{};
    *(e.data() + kDecidedKindOff) = in.Kind;
    std::memcpy(e.data() + kDecidedParentOff, in.Parent.data(), 32);
    zap::store_u64(e.data() + kDecidedHeightOff, in.Height);
    zap::store_u64(e.data() + kDecidedTimeOff, in.Time);
    return e;
}

// AppendDecided writes one Decided object into b — every payload it points at first,
