// AppendCredentials writes one Credentials object into b — every payload it points at first,
// then the object itself — and returns the object's offset.
inline std::int64_t AppendCredentials(zap::Builder& b, const CredentialsInput& in) {
    std::int64_t runs_off = 0;
    if (!in.Runs.empty()) {
        auto lb = b.start_list(8);
        for (const auto& elem : in.Runs) {
            const auto payload = EncodeCredentialRun(elem);
            lb.add_bytes(payload);
        }
        runs_off = lb.finish().first;
    }
    std::int64_t signatures_off = 0;
    if (!in.Signatures.empty()) {
        auto lb = b.start_list(65);
        for (const auto& elem : in.Signatures) lb.add_bytes(elem);
        signatures_off = lb.finish().first;
    }
    auto ob = b.start_object(kCredentialsSize);
    ob.set_list(kCredentialsRunsOff, runs_off, static_cast<std::int64_t>(in.Runs.size()));
    ob.set_list(kCredentialsSignaturesOff, signatures_off, static_cast<std::int64_t>(in.Signatures.size()));
    return ob.finish();
}

