    if (!in.Runs.empty()) {
        auto lb = b.start_list(8);
        for (const auto& elem : in.Runs) {
            const auto payload = EncodeCredentialRun(elem);
            lb.add_bytes(payload);
        }
        runs_off = lb.finish().first;
    }
    std::int64_t signatures_off = 0;
    if (!in.Signatures.empty()) {
        auto lb = b.start_list(65);
        for (const auto& elem : in.Signatures) lb.add_bytes(elem);
        signatures_off = lb.finish().first;
    }
    auto ob = b.start_object(kCredentialsSize);
